pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
    var jsonData = pm.response.json();
    if (jsonData.data && jsonData.data.token) {
        pm.collectionVariables.set("token", jsonData.data.token);
    }
    if (jsonData.data && jsonData.data.basicInfo) {
        if (jsonData.data.basicInfo.email) pm.collectionVariables.set("email", jsonData.data.basicInfo.email);
        if (jsonData.data.basicInfo.phoneNumber) pm.collectionVariables.set("phoneNumber", jsonData.data.basicInfo.phoneNumber);
    }
    try {
        var requestBody = JSON.parse(pm.request.body.raw);
        if (requestBody.password) pm.collectionVariables.set("password", requestBody.password);
    } catch (e) {}
    if (jsonData.data && jsonData.data.access) {
        pm.test("Staff access includes module menu", function () {
            var access = jsonData.data.access;
            pm.expect(access.moduleMenu).to.be.an("object");
            if (access.memberships && access.memberships.length === 1) {
                pm.expect(access.modules).to.be.an("array");
                pm.expect(access.memberships[0].modules).to.be.an("array");
            }
        });
    }
});

